#!/usr/bin/env node
// Generate the SDK's API types from the Drive OpenAPI contract.
//
//   node scripts/gen-types.mjs                     regenerate from contract/openapi.yaml
//   node scripts/gen-types.mjs --check             fail if the generated files are stale (CI)
//   node scripts/gen-types.mjs --from <drive-dir>  copy docs/api/openapi.yaml from a local untrace-drive
//                                                  checkout first and record its commit in contract/SOURCE.json
//
// Output (committed, never edited by hand):
//   packages/core/src/generated/openapi.ts     openapi-typescript output (paths, components, operations)
//   packages/core/src/generated/operations.ts  operationId -> method, path, x-status ("live" | "planned")
import { execFileSync } from "node:child_process"
import { createHash } from "node:crypto"
import { readFileSync, writeFileSync, mkdirSync } from "node:fs"
import { fileURLToPath } from "node:url"

import openapiTS, { astToString } from "openapi-typescript"
import { parse } from "yaml"

const root = fileURLToPath(new URL("../", import.meta.url))
const SPEC = `${root}contract/openapi.yaml`
const SOURCE = `${root}contract/SOURCE.json`
const OUT_DIR = `${root}packages/core/src/generated`
const args = process.argv.slice(2)
const check = args.includes("--check")
const fromIdx = args.indexOf("--from")

const sha256 = (s) => createHash("sha256").update(s).digest("hex")

if (fromIdx >= 0) {
  const drive = args[fromIdx + 1]
  if (!drive) throw new Error("--from needs the path of an untrace-drive checkout")
  const yaml = readFileSync(`${drive}/docs/api/openapi.yaml`, "utf8")
  const git = (...a) => execFileSync("git", ["-C", drive, ...a], { encoding: "utf8" }).trim()
  writeFileSync(SPEC, yaml)
  const source = {
    repo: "untracenetwork/untrace-drive",
    path: "docs/api/openapi.yaml",
    ref: git("rev-parse", "--abbrev-ref", "HEAD"),
    commit: git("rev-parse", "HEAD"),
    sha256: sha256(yaml),
  }
  writeFileSync(SOURCE, JSON.stringify(source, null, 2) + "\n")
  console.log(`contract copied from ${source.repo}@${source.commit.slice(0, 7)} (${source.ref})`)
}

const yaml = readFileSync(SPEC, "utf8")
const source = JSON.parse(readFileSync(SOURCE, "utf8"))
if (source.sha256 !== sha256(yaml)) {
  console.error("contract/openapi.yaml does not match contract/SOURCE.json. Never edit the contract by hand: run with --from <drive-dir>.")
  process.exit(1)
}

const spec = parse(yaml)
const banner = [
  "/* eslint-disable */",
  "// GENERATED by scripts/gen-types.mjs. Do not edit.",
  `// Source: ${source.repo} ${source.path} @ ${source.commit} (${source.ref})`,
  `// Contract: ${spec.info.title} ${spec.info.version}, sha256 ${source.sha256}`,
  "",
].join("\n")

const ast = await openapiTS(spec, { exportType: false, alphabetize: false, rootTypes: false })
const typesTs = banner + astToString(ast)

const METHODS = ["get", "post", "put", "patch", "delete"]
const ops = []
for (const [path, item] of Object.entries(spec.paths)) {
  for (const m of METHODS) {
    const op = item[m]
    if (!op) continue
    if (!op.operationId) throw new Error(`${m.toUpperCase()} ${path} has no operationId`)
    if (op["x-status"] !== "live" && op["x-status"] !== "planned") throw new Error(`${op.operationId} has no x-status`)
    ops.push({ id: op.operationId, method: m.toUpperCase(), path, status: op["x-status"] })
  }
}
const opsTs =
  banner +
  "/** Every operation of the contract, with its x-status. `planned` operations answer 404 until Drive ships them. */\n" +
  "export const OPERATIONS = {\n" +
  ops.map((o) => `  ${o.id}: { method: ${JSON.stringify(o.method)}, path: ${JSON.stringify(o.path)}, status: ${JSON.stringify(o.status)} },`).join("\n") +
  "\n} as const\n\n" +
  "export type OperationId = keyof typeof OPERATIONS\n" +
  `export const CONTRACT_VERSION = ${JSON.stringify(spec.info.version)}\n` +
  `export const CONTRACT_COMMIT = ${JSON.stringify(source.commit)}\n`

const outputs = { "openapi.ts": typesTs, "operations.ts": opsTs }
let stale = []
for (const [name, text] of Object.entries(outputs)) {
  const file = `${OUT_DIR}/${name}`
  if (check) {
    let cur = ""
    try {
      cur = readFileSync(file, "utf8")
    } catch {}
    if (cur !== text) stale.push(name)
  } else {
    mkdirSync(OUT_DIR, { recursive: true })
    writeFileSync(file, text)
  }
}
if (check && stale.length) {
  console.error(`generated types are stale: ${stale.join(", ")}. Run npm run gen:types and commit.`)
  process.exit(1)
}
const live = ops.filter((o) => o.status === "live").length
console.log(`${check ? "checked" : "generated"} ${ops.length} operations (${live} live, ${ops.length - live} planned) from ${source.repo}@${source.commit.slice(0, 7)}`)
